package com.contextgraph.model; import jakarta.persistence.*; @Entity @Table(name="entity_nodes") public class EntityNode {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(nullable=false) String name; @Column(nullable=false) String type; @Column(nullable=false) Long ownerId; public Long getId(){return id;} public String getName(){return name;} public String getType(){return type;} public Long getOwnerId(){return ownerId;} public void setName(String v){name=v;} public void setType(String v){type=v;} public void setOwnerId(Long v){ownerId=v;}}